CREATE TABLE productos1 (
    producto_id BIGSERIAL PRIMARY KEY,
    categoria_id BIGINT NOT NULL DEFAULT 1,
    laboratorio_id BIGINT NOT NULL DEFAULT 1,
    marca_id BIGINT NOT NULL DEFAULT 1,
    forma_id BIGINT NOT NULL DEFAULT 1,
    presentacion_id BIGINT NOT NULL DEFAULT 1,
    concentracion_id BIGINT NOT NULL DEFAULT 1,
    unidad_venta_id BIGINT NOT NULL DEFAULT 1,
    tipo_almacen_id INTEGER NOT NULL DEFAULT 1700,        -- 1700=NORMAL, 1701=REFRIGERADO, 1702=CONGELADO, 1703=ESPECIAL, 1704=TRANSITO, 1705=MATERIAL_MEDICO, 1706=COSMETICA, 1707=ALIMENTOS, 1708=MATERIA_PRIMA, 1709=RECEPCION, 1710=DEVOLUCIONES, 1711=DESPACHO, 1712=CUARENTENA
    codigo VARCHAR(100) NOT NULL,
    codigo_barras VARCHAR(100) NULL,
    sku VARCHAR(60) NULL,
    isbn VARCHAR(30) NULL,
	serie VARCHAR(60) NULL,
	modelo VARCHAR(150) NULL,
    nombre VARCHAR(600) NOT NULL,
    nombre_generico VARCHAR(600) NULL,
    pcompra DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    p_factor_venta DECIMAL(12,2) NOT NULL DEFAULT 1.50,
    p_factor_facturacion DECIMAL(12,2) NOT NULL DEFAULT 1.19,
    pventa DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    pventaf DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    stock_minimo DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    stock_maximo DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    punto_reorden DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    requiere_receta INTEGER NOT NULL DEFAULT 0,
    controlado INTEGER NOT NULL DEFAULT 0,
    tiene_registro_sanitario INTEGER NOT NULL DEFAULT 0,
    descripcion VARCHAR(3000) NULL,
    observacion VARCHAR(3000) NULL,
    foto1 VARCHAR(255) NULL,
    foto2 VARCHAR(255) NULL,
    foto3 VARCHAR(255) NULL,
    criticidad_medica_id INTEGER DEFAULT 4150,          -- 4150=NORMAL, 4151=CRITICO
    estado_id INTEGER NOT NULL DEFAULT 1000,            -- 1000=ACTIVO, 1001=BORRADO, 1002=HISTORICO
    usuario_id_registro BIGINT NOT NULL DEFAULT 1,
    usuario_id_actualizacion BIGINT NULL,
    usuario_id_baja BIGINT NULL,
    fecha_registro TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMPTZ NULL,
    fecha_baja TIMESTAMPTZ NULL,
    fts_productos1_vector tsvector GENERATED ALWAYS AS (
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(codigo, ''))), 'B') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(codigo_barras, ''))), 'B') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(sku, ''))), 'B') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(isbn, ''))), 'B') ||
		setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(serie, ''))), 'B') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(nombre, ''))), 'A') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(nombre_generico, ''))), 'A') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(marca_id::text, ''))), 'C') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(modelo, ''))), 'C') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(descripcion, ''))), 'B') ||
        setweight(to_tsvector('simple', fn_unaccent_immutable(COALESCE(observacion, ''))), 'C')
    ) STORED,
    -- CONSTRAINT fk_productos1_categoria_id FOREIGN KEY (categoria_id) REFERENCES categorias(categoria_id),
    -- CONSTRAINT fk_productos1_laboratorio_id FOREIGN KEY (laboratorio_id) REFERENCES laboratorios(laboratorio_id),
    -- CONSTRAINT fk_productos1_marca_id FOREIGN KEY (marca_id) REFERENCES marcas(marca_id),
    -- CONSTRAINT fk_productos1_forma_id FOREIGN KEY (forma_id) REFERENCES formas(forma_id),
    -- CONSTRAINT fk_productos1_presentacion_id FOREIGN KEY (presentacion_id) REFERENCES presentaciones(presentacion_id),
    -- CONSTRAINT fk_productos1_concentracion_id FOREIGN KEY (concentracion_id) REFERENCES concentraciones(concentracion_id),
    -- CONSTRAINT fk_productos1_unidad_venta_id FOREIGN KEY (unidad_venta_id) REFERENCES unidades(unidad_id),
    CONSTRAINT chk_productos1_tipoalmacenid CHECK (tipo_almacen_id IN (1700, 1701, 1702, 1703, 1704, 1705, 1706, 1707, 1708, 1709, 1710, 1711, 1712)),
    CONSTRAINT chk_productos1_estadoid CHECK (estado_id IN (1000, 1001, 1002)),
    CONSTRAINT chk_productos1_codigo_notempty CHECK (TRIM(codigo) <> ''),
    CONSTRAINT chk_productos1_codigo_minlength CHECK (LENGTH(TRIM(codigo)) >= 3),
    CONSTRAINT chk_productos1_codigo_mayusculas CHECK (codigo = UPPER(codigo)),
    CONSTRAINT chk_productos1_codigo CHECK (codigo ~ '^[A-Z0-9_-]+$'),
    CONSTRAINT chk_productos1_codigobarras_notempty CHECK (codigo_barras IS NULL OR TRIM(codigo_barras) <> ''),
    CONSTRAINT chk_productos1_sku_notempty CHECK (sku IS NULL OR TRIM(sku) <> ''),
    CONSTRAINT chk_productos1_isbn_notempty CHECK (isbn IS NULL OR TRIM(isbn) <> ''),
    CONSTRAINT chk_productos1_modelo_notempty CHECK (modelo IS NULL OR TRIM(modelo) <> ''),
    CONSTRAINT chk_productos1_nombre_notempty CHECK (TRIM(nombre) <> ''),
    CONSTRAINT chk_productos1_nombre_minlength CHECK (LENGTH(TRIM(nombre)) >= 3),
    CONSTRAINT chk_productos1_nombregenerico_notempty CHECK (nombre_generico IS NULL OR TRIM(nombre_generico) <> ''),
    CONSTRAINT chk_productos1_pfactorventa CHECK (p_factor_venta > 1),
    CONSTRAINT chk_productos1_pfactorfacturacion CHECK (p_factor_facturacion > 1),
    CONSTRAINT chk_productos1_pcompra CHECK (pcompra >= 0),
    CONSTRAINT chk_productos1_pventa CHECK (pventa >= 0),
    CONSTRAINT chk_productos1_pventaf CHECK (pventaf >= 0),
    CONSTRAINT chk_productos1_precios CHECK (
        (producto_id = 1 AND pcompra = 0 AND pventa = 0 AND pventaf = 0) OR
        (pcompra >= 0 AND pventa >= 0 AND pventaf >= 0)
    ),
    CONSTRAINT chk_productos1_stockminimo CHECK (stock_minimo >= 0),
    CONSTRAINT chk_productos1_stockmaximo CHECK (stock_maximo >= 0),
    CONSTRAINT chk_productos1_stockmaximo_stockminimo CHECK (stock_maximo >= stock_minimo),
    CONSTRAINT chk_productos1_puntoreorden CHECK (punto_reorden >= 0),
    CONSTRAINT chk_productos1_requierereceta CHECK (requiere_receta IN (0, 1)),
    CONSTRAINT chk_productos1_controlado CHECK (controlado IN (0, 1)),
    CONSTRAINT chk_productos1_tieneregistrosanitario CHECK (tiene_registro_sanitario IN (0, 1)),
    CONSTRAINT chk_productos1_descripcion_notempty CHECK (descripcion IS NULL OR TRIM(descripcion) <> ''),
    CONSTRAINT chk_productos1_observacion_notempty CHECK (observacion IS NULL OR TRIM(observacion) <> ''),
    CONSTRAINT chk_productos1_foto1_notempty CHECK (foto1 IS NULL OR TRIM(foto1) <> ''),
    CONSTRAINT chk_productos1_foto2_notempty CHECK (foto2 IS NULL OR TRIM(foto2) <> ''),
    CONSTRAINT chk_productos1_foto3_notempty CHECK (foto3 IS NULL OR TRIM(foto3) <> ''),
    CONSTRAINT chk_productos1_criticidadmedicaid CHECK (criticidad_medica_id IS NULL OR criticidad_medica_id IN (4150, 4151))
);


DELETE FROM productos1;
ALTER SEQUENCE productos1_producto1_id_seq RESTART WITH 1;




UPDATE productos1 SET usuario_id_actualizacion = NULL, fecha_actualizacion = NULL, usuario_id_baja = 1, fecha_baja = CURRENT_TIMESTAMP WHERE estado_id = 1001;
UPDATE productos1 SET usuario_id_actualizacion = 1, fecha_actualizacion = CURRENT_TIMESTAMP, usuario_id_baja = NULL, fecha_baja = NULL WHERE estado_id = 1002;

SELECT setval('productos1_producto_id_seq', COALESCE((SELECT MAX(producto_id) FROM productos1), 0), (SELECT COUNT(*) > 0 FROM productos1));
